import sys

def find_minimum_i(n, k, A):
    current_sum = 0
    for i in range(n):
        current_sum += A[i]
        if current_sum >= k:
            return 0

    previous_sums = [0] * n
    for i in range(1, n):
        previous_sums[i] = previous_sums[i-1] + A[i-1]

    for i in range(1, n):
        new_sums = [0] * n
        for j in range(1, n):
            new_sums[j] = new_sums[j-1] + (A[j-1] - previous_sums[j-1])
            if new_sums[j] >= k:
                return i
        A = new_sums[:]
        previous_sums = new_sums[:]

    return n

